-- Multi-site fixture applied on top of V001..V022 (legacy Spanish schema).
-- Canonical expectations used by SiteMergeIT:
--   canonical institution = it-inst-1 (oldest ACTIVO), canonical site = it-site-2
--   (lowest-ID ACTIVO site of it-inst-1; it-site-1 is INACTIVO and has a lower ID).
-- Colliding area codes: URG (sites 2,3,4), OBS (sites 1,4); UCI-1 is unique.
-- Duplicate active alerts: SATURACION_URGENCIAS on sites 2,3,4 (newest on site 4).

INSERT INTO INSTITUCION (PUBLIC_ID, NIT, RAZON_SOCIAL, ESTADO) VALUES ('it-inst-0', '900000000-0', 'Inactive Clinic', 'INACTIVO');
INSERT INTO INSTITUCION (PUBLIC_ID, NIT, RAZON_SOCIAL, ESTADO) VALUES ('it-inst-1', '900000001-1', 'Hospital Canonical', 'ACTIVO');
INSERT INTO INSTITUCION (PUBLIC_ID, NIT, RAZON_SOCIAL, ESTADO) VALUES ('it-inst-2', '900000002-2', 'Second Provider', 'ACTIVO');

INSERT INTO SEDE (INSTITUCION_ID, PUBLIC_ID, NOMBRE, DIRECCION, CIUDAD, ESTADO)
VALUES ((SELECT ID FROM INSTITUCION WHERE PUBLIC_ID = 'it-inst-1'), 'it-site-1', 'Closed Annex', 'Calle 1 No 1-1', 'Bogota', 'INACTIVO');
INSERT INTO SEDE (INSTITUCION_ID, PUBLIC_ID, NOMBRE, DIRECCION, CIUDAD, ESTADO)
VALUES ((SELECT ID FROM INSTITUCION WHERE PUBLIC_ID = 'it-inst-1'), 'it-site-2', 'Main Campus', 'Calle 2 No 3-4', 'Medellin', 'ACTIVO');
INSERT INTO SEDE (INSTITUCION_ID, PUBLIC_ID, NOMBRE, DIRECCION, CIUDAD, ESTADO)
VALUES ((SELECT ID FROM INSTITUCION WHERE PUBLIC_ID = 'it-inst-1'), 'it-site-3', 'North Campus', 'Calle 3 No 5-6', 'Medellin', 'ACTIVO');
INSERT INTO SEDE (INSTITUCION_ID, PUBLIC_ID, NOMBRE, DIRECCION, CIUDAD, ESTADO)
VALUES ((SELECT ID FROM INSTITUCION WHERE PUBLIC_ID = 'it-inst-2'), 'it-site-4', 'Other Provider Site', 'Calle 4 No 7-8', 'Cali', 'ACTIVO');

